    if (flow.stage === 'exception') {
      fail('已有待处理异常，请等待经营者处理', 'EXCEPTION_OPEN');
    }
    flow.exception = { id: `EX-${order.id}-${flow.events.length + 1}`, clientRequestId: requestId, note, previousStage: flow.stage, previousStatus: order.status, status: 'open', reportedAt: new Date().toISOString(), simulated: true };
